---@class MainSceneBoxFactory
MainSceneBoxFactory = class("MainSceneBoxFactory")

---@return MainSceneBoxFactory
function MainSceneBoxFactory:Get()
    if self._instance == nil then
        self._instance = MainSceneBoxFactory()
    end
    return self._instance
end

function MainSceneBoxFactory:Create()
    if MainSceneManager:Get()==nil   then
        log("MainSceneManager:Get()==nil  ")
    end
    if  MainSceneManager:Get():IsNotCreate() then
        MainSceneManager:Get().BoxInfoTable={}
        MainSceneManager:Get().ChildBoxInfoTable={}
        MainSceneManager:Get().BoxInfoTableByType={}
        local obj = SceneManager:Get():GetMainCityScenePrefab(SceneChangeID.MainCity_Interaction,true)
        if obj==nil  then
            logError("  MainCity_Interaction Is Null ")
            return


        end
        ---@type dictmainsceneinteraction_config
        local tab = ClientDataManager:Get():GetDataTable(ConfigNames.dictmainsceneinteraction_config)
        ---@type table<number,dictmainsceneinteraction_config_cell>
        local configTab = tab.GetConfigData()
        for i = 1, #configTab  do
            local boxInfo = self:CreateMainSceneBoxInfo(configTab[i],obj)
            table.insert(MainSceneManager:Get().BoxInfoTable,boxInfo)
            if MainSceneManager:Get().BoxInfoTableByType == nil then
                MainSceneManager:Get().BoxInfoTableByType={}
            end
            if MainSceneManager:Get().BoxInfoTableByType[configTab[i].funtype]==nil  then
                MainSceneManager:Get().BoxInfoTableByType[configTab[i].funtype]={}
            end
            table.insert(MainSceneManager:Get().BoxInfoTableByType[configTab[i].funtype],boxInfo)
            if boxInfo.config.parentnode~=-1 then
                if  MainSceneManager:Get().ChildBoxInfoTable== nil then
                    MainSceneManager:Get().ChildBoxInfoTable={}
                end
                if MainSceneManager:Get().ChildBoxInfoTable[configTab[i].mapnode]==nil   then
                    MainSceneManager:Get().ChildBoxInfoTable[configTab[i].mapnode]={}
                end
                table.insert(MainSceneManager:Get().ChildBoxInfoTable[configTab[i].mapnode],boxInfo)
            end
        end
    end
end

---@param config dictmainsceneinteraction_config_cell
---@param object CS.UnityEngine.GameObject
---@return MainSceneBoxInfo
function MainSceneBoxFactory:CreateMainSceneBoxInfo(config,object)
    local mainSceneBoxInfo = MainSceneBoxInfo()
    if config.rootnode~="-1" and config.rootnode~="" then
        mainSceneBoxInfo.rootObj = UIUtil.GetChild(config.rootnode,object)
    end
    mainSceneBoxInfo:SetConfig(config)
    return mainSceneBoxInfo
end

function MainSceneBoxFactory:CheckInfo()
    for  i = 1, #MainSceneManager:Get().BoxInfoTable do
        local boxInfo = MainSceneManager:Get().BoxInfoTable[i]
        self:UpdateSceneBoxInfo(boxInfo)
    end
end

---@param mainSceneBoxInfo MainSceneBoxInfo
function MainSceneBoxFactory:UpdateSceneBoxInfo(boxInfo)
    local obj = SceneManager:Get():GetMainCityScenePrefab(SceneChangeID.MainCity_Interaction,true)
    if obj==nil  then
        logError("  MainCity_Interaction Is Null ")
        return
    end
    if GameObjectIsNull(boxInfo.IBox) then
        local boxNode=UIUtil.GetChild(boxInfo.config.boxnode,obj)
        if boxNode==nil then
            logError(boxInfo.config.boxnode,"  Is Null ")
            return
        end
        boxInfo.IBox = UIUtil:AddGameobjectComponent(boxNode,typeof(CSInteractiveBox))
    end
end